ROOT=Path(__file__).resolve().parents[1]
# Each family states actual setup and movement mechanics, not a universal cue placeholder.
F={
'press':(['在平稳训练凳或器械上就位，双脚踩稳，肩胛保持有支撑。','将握把或负重对准胸部推举线，手腕与前臂大致叠放。','缓慢下降到肩部可控范围，随后推起，不靠反弹越过难点。','完成后把负重放回安全支撑，再起身。'],['肩部向前滑、耸肩或手腕明显后折。','利用胸部反弹或大幅抬臀完成推起。','没有安全支撑时尝试力竭重量。']),
'fly':(['调整凳面或滑轮高度，让上臂在可控的胸部运动平面内。','肘保持轻微弯曲，肩胛与躯干稳定。','像环抱一样让双臂向前合拢，再缓慢展开到舒适范围。','整个过程中保持肘角相对固定，不追求过大的后拉幅度。'],['把飞鸟做成大幅屈伸肘的推举。','肩向前顶或为了拉伸感强行后展。','负重过大导致耸肩和身体摆动。']),
'overhead':(['站稳或坐在有靠背的凳上，收紧腹部，避免腰部过度反弓。','将负重放在肩部附近，前臂尽量对准推举方向。','平稳向上推，给肩部留出自然活动空间，不强行挤压。','缓慢回到肩部附近，保持躯干和手腕稳定。'],['过度后仰，把肩推做成腰部借力。','为了推得更高而耸肩、失去肋骨控制。','下降过深或使用无法控制还原的重量。']),
'raise':(['选择能稳定控制的轻负重，站稳或坐稳，肩颈放松。','肘保持轻微弯曲，沿当前动作指定的前方或侧方抬臂。','抬到肩部舒适的高度即可，停顿后缓慢放下。','保持躯干稳定，感受肩部带动上臂，而不是甩动负重。'],['耸肩、快速甩动身体。','为了更高幅度强行抬臂或内旋挤压肩部。','屈肘幅度不断变化，变成弯举或划船。']),
'rear':(['根据器材俯身或面向胸托，固定躯干与髋部位置。','肘略弯，让上臂向两侧后方打开。','在肩部可控范围内停顿，不用腰部抬起负重。','缓慢让手臂回到起点，保持前后每次幅度一致。'],['把动作做成大幅屈肘的划船。','抬起躯干借力、过度挺腰。','耸肩或后拉超过肩部舒适范围。']),
'row':(['先设置支撑或俯身角度，维持脊柱自然姿势。','肩部随负重自然前伸但不松垮塌腰。','肘向后拉向躯干附近，让负重朝下胸或腰部移动。','控制还原，避免躯干大幅前后摆动。'],['用腰部猛拉或每次改变躯干角度。','耸肩、用手腕勾起负重。','还原时突然松手或让肩部被重量拖拽。']),
'pulldown':(['调节座椅和压腿垫，坐稳并确认握把与握法。','手臂向上伸展，保持腹部与骨盆稳定。','肘向下带动握把靠近上胸前方，避免从颈后拉下。','缓慢伸臂还原，不把身体甩回起点。'],['大幅后仰并靠惯性拉动。','把握把拉向颈后或强行碰胸。','握法与器材不符，忽视压腿垫和安全卡扣。']),
'pullup':(['检查单杠和握把稳固，选择动作指定握法。','在可控悬垂中稳定肩胛，腹部保持张力。','屈肘向上拉起身体，不靠摆腿或甩腰。','控制下降到可承受的伸臂位置，再开始下一次。'],['摆动、蹬腿或过度抬下巴来凑高度。','肩部突然松脱、自由下落。','把正握、反握和对握当成完全相同的握法。']),
'squat':(['站距按髋部舒适范围设置，脚掌稳固接触地面。','吸气建立躯干张力，髋膝一起屈曲下蹲。','保持膝盖大体随脚尖方向移动，下蹲到仍可控制的深度。','通过脚掌推地站起，避免最后用腰部后仰顶起。'],['脚跟抬起、膝部突然内扣。','追求深度而明显塌腰或失去骨盆控制。','出杠、回杠或保护设置不充分。']),
'lunge':(['握稳负重或徒手站稳，预留前后及左右空间。','按当前变式迈步或保持分腿站距，让前脚稳固落地。','髋膝受控弯曲，后膝接近地面但不撞地。','由前脚推地回到该变式的起点，两侧分别完成。'],['像走钢丝一样两脚排成一条线，导致失衡。','膝盖内扣或落地时突然砸下。','前脚未站稳就急着换腿或增加重量。']),
'hinge':(['负重靠近身体，双脚站稳，建立腹部与背部张力。','膝关节适度弯曲，髋向后移动而不是只弯腰。','负重贴近腿部移动，到背部仍可稳定的位置为止。','通过伸髋站起，顶端保持直立，不向后折腰。'],['弓背猛拉或让负重远离身体。','用深蹲代替髋铰链，或把膝盖完全锁死。','在腰背失去控制后继续追求更低幅度。']),
'bridge':(['仰卧在平整垫面，屈膝踩稳双脚。','收紧腹部，肩背保持支撑，负重如有则扶稳在髋部。','通过脚掌推地抬髋，到肩髋膝大致成一直线。','缓慢降低骨盆，不用腰部过度伸展完成抬高。'],['腰部过度反弓而不是伸髋。','脚的位置过远或过近，导致发力失控。','负重没有扶稳，或把它压在腹部/骨性部位。']),
'hipthrust':(['将上背靠在稳固训练凳边缘，脚掌踩稳。','负重放在髋部并用衬垫和双手稳住。','下颌自然收回，控制骨盆下降后伸髋抬起。','顶端保持腹部张力，再缓慢下降，勿过度折腰。'],['凳子滑动或支撑点在颈部。','负重在髋部滚动。','抬头后仰并用腰部顶高。']),
'legcurl':(['调节座椅、压垫或脚踝滚垫，让器械转轴大致对齐膝关节。','稳定骨盆与躯干，握住支撑把手。','屈膝将滚垫向身后或座椅下方带动。','缓慢伸膝还原，避免配重片撞击。'],['骨盆抬起或腰部拱起借力。','滚垫压在关节、脚跟或小腿不合适的位置。','动作过快，让配重直接落下。']),
'legextension':(['调整靠背和脚踝垫，让膝关节与转轴相近。','坐稳并固定大腿，不把身体抬离座椅。','受控伸膝抬起滚垫，到舒适范围后稍停。','缓慢弯膝还原，不用惯性甩动。'],['靠腰背后仰或抬臀完成伸膝。','器械轴线和膝关节明显错位。','负重过大，无法平稳控制下降。']),
'calf':(['确认前脚掌有稳固支撑，足弓和脚踝对齐。','按站姿或坐姿版本固定膝角和负重位置。','主要通过踝关节缓慢抬高脚跟，再受控降低。','在自身可控范围内练习，单腿版本两侧分别完成。'],['用膝部反复屈伸代替踝部提踵。','依靠弹震快速上下。','负重滑动，或让脚掌边缘失去支撑。']),
'curl':(['站稳或坐稳，按动作要求设置正握、反握或对握。','上臂位置保持稳定，手腕尽量与前臂一致。','主要通过屈肘抬起负重，不用腰部甩起。','缓慢伸肘还原，不把手臂突然放松。'],['前后摆动身体或把肘大幅向前抬。','手腕过度弯折。','只抬起、不控制下降，或每次握法变化。']),
'extension':(['确认凳面或站姿稳定，让上臂处于可控位置。','握稳负重，肘关节缓慢弯曲，负重远离面部。','保持上臂相对稳定，通过伸肘还原。','结束时先安全放下负重，再改变身体姿势。'],['把肩部大幅摆动当成伸肘。','负重压向头脸或超出肩肘舒适范围。','肘部受力失控或靠甩动完成。']),
'pushdown':(['将滑轮或阻力带固定在高位，确认连接可靠。','站稳，肘靠近躯干，前臂与握把方向协调。','主要通过伸肘将握把下压，不让上臂大幅前后移动。','缓慢屈肘还原，保持躯干稳定。'],['用体重趴压或抖动肩部。','手腕后折、肘向外散开。','还原过快，配重和绳索突然松弛。']),
'dip':(['检查双杠或辅助器械稳固，双手握紧支撑。','保持肩部有控制，受控屈肘降低身体。','只下降到肩部舒适范围，再通过伸肘推起。','用脚台或安全支撑进出器械，不突然跳下。'],['肩部前顶、耸肩或下降过深。','摆腿借力或肘部突然锁死。','把平凳臂屈伸和双杠臂屈伸的支撑条件混用。']),
'wrist':(['坐稳或站稳并给前臂可靠支撑，握住轻负重。','保持肘部与前臂相对固定。','主要由腕关节按掌屈或背伸方向缓慢移动。','用小而受控的幅度还原，避免甩动。'],['用屈肘或耸肩抬起负重。','负重过大造成手腕被动折弯。','失去握持控制，或追求疼痛的末端角度。']),
'shrug':(['双脚站稳，双臂自然下垂持稳负重。','保持头颈自然，肩部向上抬起。','在可控顶端短暂停顿后缓慢放下。','手臂保持自然，不做大幅屈肘。'],['肩部画圈或用颈部前伸代偿。','借助膝髋弹跳甩起。','握持重量超过控制能力，导致突然掉落。']),
'carry':(['选择可稳固握持的负重，先在原地站直。','腹部保持张力，肩部自然，目视前方。','用小而稳定的步幅行走，保持左右平衡。','到指定位置后先站稳，再受控放下负重。'],['耸肩、歪斜或屏住气强撑。','步幅过大，在转弯时晃动负重。','走到力竭才匆忙放下。']),
'crunch':(['仰卧或按指定器材固定身体，稳定骨盆。','呼气时让胸廓靠近骨盆，主要抬起肩胛附近。','在腹部仍可控制的幅度稍停。','缓慢还原，不用手拉头或靠惯性坐起。'],['用手臂拉扯颈部。','把小幅卷腹做成大幅甩动的仰卧起坐。','腰部失控或负重压在头颈上。']),
'legraise':(['仰卧或在可靠支撑架就位，稳定肩部与骨盆。','保持腹部张力，按当前变式屈膝或伸腿抬起。','不要靠摆动把双腿甩高。','缓慢降低双腿，到腰背仍受控的位置停止。'],['下放时腰部明显反弓。','摆腿和借力幅度大于主动控制。','支撑或握持不足却追求大幅度。']),
'plank':(['将手或肘放在肩部附近的可靠支撑面上。','收紧腹部与臀部，让躯干保持稳定。','按当前静态或交替移动版本练习，保持平稳呼吸。','失去躯干控制前结束并安全回到支撑面。'],['塌腰、抬臀或持续耸肩。','屏气或为了时长而维持变形姿势。','交替动作时骨盆大幅旋转。']),
'rotation':(['按坐姿或站姿要求固定脚和骨盆，握稳轻负重或绳索。','先建立腹部张力，保持脊柱舒适姿势。','控制胸廓和肩带按动作方向转动，不甩动腰部。','缓慢回到中间，再练另一方向。'],['扭动幅度超过控制能力。','用手臂甩重物带着腰部转动。','双脚或骨盆意外滑动。']),
'antirotation':(['将阻力固定在身体侧方，站姿或跪姿稳固。','双手将握把放在胸前，腹部保持张力。','向前推出或保持静止，同时抵抗身体被拉向侧面。','缓慢收回，换边重新设置身体方向。'],['让躯干跟着绳索旋转。','耸肩或腰部后仰来抵抗阻力。','固定点松动或负重过大。']),
'hipabduction':(['侧卧、站立或坐在器械上，先稳定骨盆。','按指定变式把大腿向身体外侧打开。','只移动到骨盆仍能保持稳定的位置。','缓慢还原，单侧动作两侧分别练习。'],['躯干侧倾或骨盆翻转来凑幅度。','用摆动代替髋部主动控制。','阻力带或器械压垫落在关节上。']),
'hipadduction':(['在器械或侧向绳索旁就位，固定躯干与骨盆。','将练习侧大腿向身体中线靠近。','保持小而可控的运动范围，不用身体猛拉。','缓慢向外还原，再换另一侧。'],['身体跟着侧倒。','跨越过大幅度并突然碰撞支撑腿。','连接带或器械垫位置不可靠。']),
'kickback':(['扶稳支撑或四点跪姿就位，保持骨盆朝向稳定。','练习侧腿向后伸髋，不靠腰部反弓抬高。','在臀部仍可控制的范围稍停。','缓慢还原，两侧分别完成。'],['用腰部后仰代替伸髋。','骨盆向外翻转。','腿摆得过高或绳索/阻力带突然弹回。']),
'backextension':(['调整支撑垫，使髋部能够活动而腹部不被顶压。','先建立腹部张力，保持头颈自然。','从髋部缓慢折叠，再伸髋回到躯干接近直线。','不要超过直线位置大幅后仰。'],['用腰椎反复折叠代替髋部运动。','快速弹起或甩头。','支撑垫位置过高或脚部固定不稳。']),
'crawl':(['在平整防滑地面就位，双手支撑，稳定肩髋。','保持躯干张力，按动作要求交替移动手脚。','每次移动距离小，尽量不让身体左右晃动。','先站稳或回到四点支撑后结束。'],['移动过快而塌腰、扭髋。','手腕或肩部支撑失控。','前进空间不足仍继续动作。']),
'cardio':(['调整器械或选择平整安全的路线，确认可顺利停止。','从可控制的低强度开始，保持自然呼吸。','逐步达到事先选择的节奏，不靠扶手吊住体重。','结束时降低速度或阻力，稳定后离开。'],['一开始就选无法维持的速度或阻力。','姿势塌陷，靠扶手承重。','器械尚未停稳就离开。']),
'jump':(['在平整防滑地面站稳，预留手脚活动空间。','髋膝保持弹性，按当前变式小幅起跳或快速换步。','落地时髋膝共同缓冲，保持膝盖随脚尖方向。','先保持节奏与落地控制，再增加速度。'],['膝盖内扣或落地僵硬。','为了速度放弃躯干稳定。','空间不足或明显疲劳时继续冲刺。'])}

def add(key,steps,errors):F[key]=(steps,errors)
add('deadbug',['仰卧，髋膝屈曲并将双手伸向上方。','保持腰背受控，一侧手臂与对侧腿缓慢伸远。','在腰部未反弓前停下并回到起点。','换另一侧练习，保持平稳呼吸。'],['同侧手脚一起移动却当成标准对侧版本。','腰部离地过多。','为了伸直而失去腹部控制。'])
add('birddog',['四点跪姿，手在肩下、膝在髋下。','稳定躯干，将一侧手臂与对侧腿伸远。','保持骨盆朝下，不追求抬得更高。','缓慢收回后换侧。'],['骨盆侧翻或腰部反弓。','伸手抬腿时突然转移体重。','耸肩或缩颈。'])
add('abwheel',['跪在垫上，双手握稳健腹轮，确认滚动路径。','收紧腹部和臀部，慢慢向前滚动。','只到腹部仍可控制、腰部不下塌的位置。','用躯干张力把轮子收回，不靠猛屈髋甩回。'],['腰部塌陷或突然滚得过远。','把动作做成只伸手、不稳定躯干。','没有掌握跪姿就直接尝试站姿大幅前滚。'])
add('rowingmachine',['调节脚带并稳固坐在划船机上。','先用腿推开，再伸髋、最后屈肘收把。','回程先伸臂，再屈髋，最后屈膝回座。','保持背部自然，手柄路径平稳。'],['先用手猛拉。','弓背或膝先抬起挡住手柄。','回座过快，撞击行程末端。'])
add('swim',['只采用已经掌握的泳姿，在具备安全保障的泳池练习。','入水后先建立可持续呼吸节奏。','按泳姿协调手臂划水与腿部动作，不在疲劳时勉强憋气。','靠近池边稳定后结束；本条不提供水下自学或救生指导。'],['将陆上器械姿势当成完整游泳教学。','过度憋气或超过自身水中能力。','呼吸紊乱后仍继续加速。'])
add('shrimp',['先用稳固支撑帮助平衡，站在练习侧腿上。','另一腿向后屈膝，保持练习侧脚掌稳固。','练习侧髋膝缓慢弯曲，后膝靠近地面。','由支撑脚推地回到站姿，再换侧。'],['把自由腿向前伸的手枪蹲当成虾式蹲。','支撑腿膝部内扣。','先追求深度而失去平衡。'])
add('clam',['侧卧，髋膝适度弯曲，骨盆保持叠放。','双脚保持接近，上侧膝缓慢向外打开。','只打开到骨盆不向后翻的位置。','缓慢合拢后换另一侧。'],['把上侧腿伸直变成侧卧抬腿。','腰或骨盆向后翻。','阻力带直接压住膝关节。'])
add('bandpullapart',['站稳，双手在胸前握住阻力带。','肘略弯，肩部放松。','双手向两侧拉开，保持躯干稳定。','受控回到胸前，不让带子突然弹回。'],['耸肩或过度挺胸折腰。','阻力过大导致屈肘拉扯。','使用有裂纹的阻力带。'])
add('hollow',['仰卧，先屈膝并让腰背保持受控。','抬起肩胛与腿，按能力逐渐伸远四肢。','在不塌腰的角度静止保持；摇摆版本保持身体整体张力。','失去腰背控制前结束或回到屈膝版本。'],['用大幅甩动代替整体张力。','把V字坐起当成静态中空体式。','为了伸直腿而让腰部悬空失控。'])
add('lsit',['在稳固平行支撑上握紧或撑稳双手。','肩部主动支撑，先练屈膝悬空。','在能稳定肩髋的位置逐渐伸腿到前方。','失去支撑前缓慢落脚，不靠颈肩硬撑。'],['支撑松动或耸肩塌下。','突然甩腿抬高。','没有掌握屈膝支撑就强行伸腿。'])
add('dragon',['仅在已掌握基础核心控制后，先用屈膝缩短力臂的版本。','肩背稳定接触训练凳，双手握住可靠固定处，颈部不承重。','保持躯干张力，在可控范围内缓慢降低髋腿。','控制不足时屈膝退出，不从高位坠落。'],['把杠上前水平当成凳上龙旗。','用颈部顶住身体。','没有安全退出能力就尝试长力臂。'])
add('hang',['检查单杠，选择能稳固握住的位置。','双脚借助踏台逐渐离开支撑，不突然跳挂。','按被动或主动版本控制肩胛，保持平稳呼吸。','握持下降前让脚重新回到安全支撑。'],['突然松手坠落。','肩部不适仍继续悬垂。','把主动肩胛控制等同于反复屈肘。'])
add('skater',['站在练习侧腿上，另一腿向后屈曲。','保持骨盆平稳，练习侧髋膝慢慢弯曲。','后膝靠近地面但不撞地。','从练习侧脚掌推地站起，再换侧。'],['混入双腿深蹲或侧弓步。','膝部内扣、身体突然侧倒。','为了触地而弯腰失去骨盆控制。'])
# Mobility movements have separate mechanics rather than one shared stretching paragraph.
M={
'cat-cow-stretch':('四点跪姿，手在肩下、膝在髋下。','缓慢圆背，再轻柔回到舒适的伸展位置，配合呼吸。','不要快速甩头或强行压腰。'),
'arm-circles':('站稳，双臂在肩部舒适高度展开。','从小圆开始缓慢绕环，按能力调整方向和幅度。','不要靠耸肩或甩动完成大圆。'),
'worlds-greatest-stretch':('从有双手支撑的低弓步进入。','保持前脚稳固，胸廓缓慢向前腿侧转开，再还原。','不要强压前膝或用腰部猛扭。'),
'leg-swings-stretch':('扶稳固定支撑，站立腿微屈。','让另一腿在可控范围内前后摆动，再换腿。','不要用腰部甩动或追求过高幅度。'),
'torso-twist-stretch':('站稳或坐稳，双脚有支撑。','在无负重状态下让胸廓轻柔左右转动。','不要把负重俄罗斯转体当成轻度活动。'),
'doorway-chest-stretch':('将前臂或手放在稳固门框上，肩部保持舒适。','小步向前移动躯干，到胸部轻度牵拉的位置。','不要把上臂硬拉到身体后方。'),
'childs-pose':('跪在垫上，选择膝部舒适间距。','臀部缓慢向脚跟方向靠近，手臂向前伸。','不要强压膝部或为了贴地而屏气。'),
'kneeling-hip-flexor-stretch':('半跪姿，后膝垫软垫、前脚踩稳。','轻收骨盆，躯干保持直立，缓慢向前平移。','不要通过腰部后弯来制造拉伸感。'),
'hamstring-stretch':('将一脚放在低而稳固的支撑上，膝保持舒适。','从髋部轻轻前倾，到大腿后侧轻度牵拉。','不要弓背猛压或把支撑抬得过高。'),
'standing-quad-stretch':('扶稳支撑，站立腿微屈。','另一侧屈膝，用手轻扶脚踝，骨盆保持稳定。','不要将膝盖硬拉到身后或反弓腰部。'),
'seated-forward-fold-stretch':('坐稳，双腿向前，膝部可按能力微屈。','从髋部缓慢前倾，手自然伸向小腿或脚部。','不要拉脚强拽身体或弹震。'),
'cross-body-shoulder-stretch':('站稳或坐稳，一臂横过胸前。','另一手轻扶上臂，使肩部出现舒适牵拉。','不要压肘关节或强行拉到疼痛。'),
'wall-calf-stretch':('双手扶墙，一脚向后站稳，脚尖朝前。','后脚跟保持接近地面，缓慢将重心前移。','不要让后脚外翻或用弹震压脚跟。'),
'butterfly-stretch':('坐稳，脚掌相对，双手轻扶脚部。','脊柱保持舒适，从髋部轻柔前倾。','不要用肘部大力压膝。')}
for k,(a,b,c) in M.items():add(k.strip(),[a,b,'只到轻度牵拉范围，保持自然呼吸。','缓慢退出后再换侧或方向。'],[c,'拉伸中出现关节疼痛或麻木仍强行继续。','用快速弹震代替受控移动。'])

